const LEAD = 2 * 3600;
const covered = {};
for (const it of $('Read nightly log').all()) {
  const r = it.json || {};
  if (!r.project_id || !r.audited_at) { continue; }
  const t = Math.floor(new Date(r.audited_at).getTime() / 1000) - LEAD;
  if (t > windowStart && t <= nowS) { covered[r.project_id] = Math.max(covered[r.project_id] || 0, t); }
}
const runDate = $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd');
return active.map(function (p) { return { json: { project_id: p.project_id, project_name: clean(p.project_name), since_ts: Math.max(windowStart, covered[p.project_id] || 0), nightly_covered: !!covered[p.project_id], run_date: runDate } }; });

// One scan per project x target language. Language ids are taken from each project (they differ per project).
