// Collect the changed keys per project + language and split them into chunks the worker fetches with filter_key_ids.
const jobs = $('Build scan jobs').all().map(function (i) { return i.json; });
const res = $input.all().map(function (i) { return i.json || {}; });
const CHUNK = 200;
