  if ((r.errors || []).length) { scanErrors.push(j.project_name + ' / ' + j.lang_name + ': ' + r.errors.join('; ').slice(0, 200)); }
  const ids = [];
  for (const c of (r.changed || [])) { if (skipped(c)) { excluded++; continue; } if (ids.indexOf(c.key_id) === -1) { ids.push(c.key_id); } }
  total += ids.length;
  for (let s = 0; s < ids.length; s += CHUNK) { groups.push(Object.assign({}, j, { key_ids: ids.slice(s, s + CHUNK).join(','), chunk: s / CHUNK, changed_count: ids.length })); }
