  if (f.check === 'Style' || f.check === 'Style guide') { const u = guideFor(l.name); return u ? { url: u, label: l.name + ' style guide' } : { url: '', label: '' }; }
  return { url: '', label: '' };
}
const a = $('Aggregate results').first().json;
const out = [];
let n = 0;
for (const l of a.langs) {
  for (const f of l.findings) {
    n++;
    const ref = reference(l, f);
    out.push({ json: { 'Decision': '', 'Reason (required if Rejected)': '', ID: 'F' + String(n).padStart(4, '0'), Language: l.name, Project: l.project, ISO: l.iso,
      'Linguist edit': f.linguist_edit ? 'Yes' : 'No', 'Last edited by': f.last_edited_by || '(unknown)', Check: f.check, Severity: f.severity, 'Rule / term': f.rule, Key: f.key,
      'Key description': f.key_description || '', English: String(f.en || '').slice(0, 30000), Translation: String(f.translation || '').slice(0, 30000),
      Issue: f.issue, Suggestion: f.suggestion, Reference: ref.url, 'Reference label': ref.label, 'Found by': f.found_by } });
  }
}
return out;

// One review tab per language, then the empty 'Findings' tab is removed.
const cs = $('Create review sheet').first().json;
const rows = $('Build findings rows').all().map(function (i) { return i.json; });
const titles = [];
for (const r of rows) { const t = String(r.Language || r.ISO || 'Other').slice(0, 90); if (titles.indexOf(t) === -1) { titles.push(t); } }
const f = (cs.sheets || []).filter(function (s) { return s.properties && s.properties.title === 'Findings'; })[0];
const requests = titles.map(function (t, i) { return { addSheet: { properties: { title: t, index: i, gridProperties: { frozenRowCount: 1 } } } }; });
if (f) { requests.push({ deleteSheet: { sheetId: f.properties.sheetId } }); }
return [{ json: { spreadsheetId: cs.spreadsheetId, titles: titles, addBody: { requests: requests } } }];

const plan = $('Plan language tabs').first().json;
const resp = $input.first().json || {};
const ids = {};
for (const r of (resp.replies || [])) { if (r && r.addSheet) { ids[r.addSheet.properties.title] = r.addSheet.properties.sheetId; } }
// Visible layout: 'Linguist edit' (Yes / No) and 'Last edited by' show who last changed the translation; 'Reference' links the
// Lokalise glossary or the language's style guide; Decision and Reason last. A reason is REQUIRED for every Rejected row
// (Maria 2026-10-13): empty reasons on Rejected rows are highlighted red and the review ingest refuses the sheet until they are filled.
const HEAD = ['Language', 'Project', 'Linguist edit', 'Last edited by', 'Check', 'Severity', 'Rule / term', 'Key', 'Key description', 'English', 'Translation', 'Issue', 'Suggestion', 'Reference', 'Decision', 'Reason (required if Rejected)'];
const DEC = HEAD.indexOf('Decision');
const REA = HEAD.indexOf('Reason (required if Rejected)');
const REF = HEAD.indexOf('Reference');
const LING = HEAD.indexOf('Linguist edit');
const col = function (i) { return String.fromCharCode(65 + i); };
const Q = String.fromCharCode(39);
// Text wrap on every tab by default (Maria 2026-10-07); long-text columns widened so wrapped rows stay readable.
const WIDE = ['Key', 'Key description', 'English', 'Translation', 'Issue', 'Suggestion', 'Reason (required if Rejected)'];
const by = {};
const links = {};
for (const it of $('Build findings rows').all()) {
  const r = it.json; const t = String(r.Language || r.ISO || 'Other').slice(0, 90);
  (by[t] = by[t] || []).push(HEAD.map(function (h) { return r[h] === undefined || r[h] === null ? '' : String(r[h]); }));
  (links[t] = links[t] || []).push(r.Reference ? { url: String(r.Reference), label: String(r['Reference label'] || 'Link') } : null);
}
const data = [];
const reqs = [];
for (const t of plan.titles) {
  const body = by[t] || [];
  const vals = [HEAD].concat(body);
  data.push({ range: Q + t.split(Q).join(Q + Q) + Q + '!A1', values: vals });
  const sid = ids[t];
  if (sid === undefined) { continue; }
  reqs.push({ repeatCell: { range: { sheetId: sid }, cell: { userEnteredFormat: { wrapStrategy: 'WRAP', verticalAlignment: 'TOP' } }, fields: 'userEnteredFormat.wrapStrategy,userEnteredFormat.verticalAlignment' } });
  for (const h of WIDE) { const c = HEAD.indexOf(h); if (c !== -1) { reqs.push({ updateDimensionProperties: { range: { sheetId: sid, dimension: 'COLUMNS', startIndex: c, endIndex: c + 1 }, properties: { pixelSize: 320 }, fields: 'pixelSize' } }); } }
  reqs.push({ updateDimensionProperties: { range: { sheetId: sid, dimension: 'COLUMNS', startIndex: REF, endIndex: REF + 1 }, properties: { pixelSize: 170 }, fields: 'pixelSize' } });
  reqs.push({ repeatCell: { range: { sheetId: sid, startRowIndex: 0, endRowIndex: 1 }, cell: { userEnteredFormat: { textFormat: { bold: true } } }, fields: 'userEnteredFormat.textFormat.bold' } });
  // Clickable links as rich text (label + link), NOT a HYPERLINK formula: the sheets are created with locale es_ES,
  // where a comma-separated formula renders #ERROR! (2026-10-08). Rich-text links work in every sheet locale.
  (links[t] || []).forEach(function (lk, i) {
    if (!lk) { return; }
    reqs.push({ updateCells: { start: { sheetId: sid, rowIndex: i + 1, columnIndex: REF }, rows: [{ values: [{ userEnteredValue: { stringValue: lk.label }, textFormatRuns: [{ startIndex: 0, format: { link: { uri: lk.url } } }] }] }], fields: 'userEnteredValue,textFormatRuns' } });
  });
  reqs.push({ setDataValidation: { range: { sheetId: sid, startRowIndex: 1, endRowIndex: vals.length, startColumnIndex: DEC, endColumnIndex: DEC + 1 }, rule: { condition: { type: 'ONE_OF_LIST', values: [{ userEnteredValue: 'Approved' }, { userEnteredValue: 'Rejected' }] }, showCustomUi: true, strict: true } } });
  // Red highlight on an empty reason when the row is Rejected. The formula uses no argument separators, so it works in the es_ES sheet locale.
  reqs.push({ addConditionalFormatRule: { index: 0, rule: { ranges: [{ sheetId: sid, startRowIndex: 1, endRowIndex: vals.length, startColumnIndex: REA, endColumnIndex: REA + 1 }], booleanRule: { condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: '=$' + col(DEC) + '2&LEN($' + col(REA) + '2)="Rejected0"' }] }, format: { backgroundColor: { red: 0.96, green: 0.78, blue: 0.78 } } } } } });
  // Linguist edit = Yes shown in amber so report-only rows stand out.
  reqs.push({ addConditionalFormatRule: { index: 0, rule: { ranges: [{ sheetId: sid, startRowIndex: 1, endRowIndex: vals.length, startColumnIndex: LING, endColumnIndex: LING + 1 }], booleanRule: { condition: { type: 'TEXT_EQ', values: [{ userEnteredValue: 'Yes' }] }, format: { backgroundColor: { red: 1, green: 0.9, blue: 0.7 } } } } } });
}
return [{ json: { spreadsheetId: plan.spreadsheetId, valuesBody: { valueInputOption: 'RAW', data: data }, validationBody: { requests: reqs } } }];
